target_date = "2023-05-16"
splitwise_invites = []
for msg in voice_messages:
    if msg['sent_at'].startswith(target_date):
        if "splitwise group invitation" in msg['message']:
            splitwise_invites.append(msg)

print("Splitwise invitations on May 16:")
for msg in splitwise_invites:
    print(f"ID: {msg['voice_message_id']}, Sender: {msg['sender']['name']} ({msg['sender']['phone_number']}), contact_id: {msg['sender']['contact_id']}")

# Build set of contact phone numbers
contact_phones = set()
for contact in contacts:
    contact_phones.add(contact['phone_number'])

print("\nContact phone numbers:", contact_phones)

# Check each invite sender
for msg in splitwise_invites:
    sender_phone = msg['sender']['phone_number']
    in_contacts = sender_phone in contact_phones
    print(f"Message {msg['voice_message_id']} from {sender_phone} in contacts: {in_contacts}")

